<script setup lang="ts">
import { computed, inject } from 'vue'
import { useMilestoneCompletion } from '@/dashboard/composables/useMilestoneCompletion'
import { usePagination } from '@/dashboard/composables/usePagination'
import { STATUS_META } from '@/dashboard/constants/status'
import { FED_SEARCH_KEY, PROJECT_MILESTONES_KEY } from '@/dashboard/injectionKeys'
import { parseMonthLabel, shortMonth } from '@/dashboard/utils/date'
import { SIDE_LABELS, type MilestoneSide } from '@/dashboard/utils/milestones'
import type { MetricItem, Milestone } from '@/dashboard/types/project'
import MetricStrip from './common/MetricStrip.vue'
import PaginationBar from './common/PaginationBar.vue'
import ProjectThumb from './common/ProjectThumb.vue'
import StatusBadge from './common/StatusBadge.vue'

interface MonthColumn {
  key: string
  label: string
  year: number
  monthIdx: number
}

const PROJECTS_PER_PAGE = 10

// ── Injected live data ───────────────────────────────────────────────────────
const { loading: fedLoading } = inject(FED_SEARCH_KEY)!
const {
  projects,
  customerMarkersByProject,
  indoMarkersByProject,
  loading: milestonesLoading,
  loadedCount,
  totalCount,
} = inject(PROJECT_MILESTONES_KEY)!

const isLoading = computed(() => fedLoading.value || milestonesLoading.value)

// ── Month columns: derived from the projects' date range ────────────────────
function buildMonthRange(start: Date, end: Date): MonthColumn[] {
  const cols: MonthColumn[] = []
  const cur = new Date(start.getFullYear(), start.getMonth(), 1)
  while (cur <= end) {
    cols.push({
      key: `${cur.getFullYear()}-${cur.getMonth()}`,
      label: shortMonth(cur),
      year: cur.getFullYear(),
      monthIdx: cur.getMonth(),
    })
    cur.setMonth(cur.getMonth() + 1)
  }
  return cols
}

const monthColumns = computed<MonthColumn[]>(() => {
  if (!projects.value.length) {
    const now = new Date()
    return buildMonthRange(
      new Date(now.getFullYear(), now.getMonth() - 1, 1),
      new Date(now.getFullYear(), now.getMonth() + 10, 1),
    )
  }

  let minDate: Date | null = null
  let maxDate: Date | null = null
  const include = (date: Date | null) => {
    if (!date) return
    if (!minDate || date < minDate) minDate = date
    if (!maxDate || date > maxDate) maxDate = date
  }

  for (const p of projects.value) {
    const start = p.estimatedStartDate ? new Date(p.estimatedStartDate) : null
    const end = p.estimatedFinishDate ? new Date(p.estimatedFinishDate) : null
    if (start && (!minDate || start < minDate)) minDate = start
    if (end && (!maxDate || end > maxDate)) maxDate = end
  }

  // Extend the range to cover every marker (Indo + Customer)
  for (const markers of [
    ...Object.values(indoMarkersByProject.value),
    ...Object.values(customerMarkersByProject.value),
  ]) {
    markers.forEach((m) => include(parseMonthLabel(m.dateLabel)))
  }

  const start: Date = minDate ?? new Date()
  const end: Date = maxDate ?? new Date(start.getFullYear(), start.getMonth() + 6, 1)

  return buildMonthRange(
    new Date(start.getFullYear(), start.getMonth() - 1, 1),
    new Date(end.getFullYear(), end.getMonth() + 1, 1),
  )
})

// ── Current month highlight ──────────────────────────────────────────────────
const today = new Date()

function isCurrentMonth(col: MonthColumn): boolean {
  return col.year === today.getFullYear() && col.monthIdx === today.getMonth()
}

function isYearStart(colIdx: number): boolean {
  return colIdx > 0 && monthColumns.value[colIdx - 1]!.year !== monthColumns.value[colIdx]!.year
}

// ── Year header groups ───────────────────────────────────────────────────────
const yearGroups = computed(() => {
  const spans = new Map<number, number>()
  for (const col of monthColumns.value) {
    spans.set(col.year, (spans.get(col.year) ?? 0) + 1)
  }
  return Array.from(spans.entries()).map(([year, span]) => ({ year, span }))
})

// ── Pagination ───────────────────────────────────────────────────────────────
const {
  currentPage,
  pageSize,
  totalPages,
  totalItems,
  rangeStart,
  rangeEnd,
  pageItems: pagedProjects,
} = usePagination(projects, PROJECTS_PER_PAGE)

// ── Marker placement ─────────────────────────────────────────────────────────
/**
 * Each project shows two milestone rows: Indo first (square markers),
 * then Customer (circle markers).
 */
const ROW_SIDES: MilestoneSide[] = ['INDO', 'CUSTOMER']

function markersFor(projectId: string, side: MilestoneSide): Milestone[] {
  const source = side === 'INDO' ? indoMarkersByProject : customerMarkersByProject
  return source.value[projectId] ?? []
}

function isInColumn(dateLabel: string, col: MonthColumn): boolean {
  const date = parseMonthLabel(dateLabel)
  return !!date && date.getFullYear() === col.year && date.getMonth() === col.monthIdx
}

function columnIndexOf(dateLabel: string): number {
  return monthColumns.value.findIndex((col) => isInColumn(dateLabel, col))
}

function markersAt(projectId: string, side: MilestoneSide, col: MonthColumn): Milestone[] {
  return markersFor(projectId, side).filter((m) => isInColumn(m.dateLabel, col))
}

/** Connector-line classes for a cell, spanning the first → last marker of a row. */
function trackClasses(projectId: string, side: MilestoneSide, colIndex: number) {
  const markers = markersFor(projectId, side)
  if (markers.length < 2) return {}

  const indices = markers.map((m) => columnIndexOf(m.dateLabel)).filter((i) => i >= 0)
  if (indices.length < 2) return {}

  const firstIdx = Math.min(...indices)
  const lastIdx = Math.max(...indices)
  return {
    'track-left': colIndex > firstIdx && colIndex <= lastIdx,
    'track-right': colIndex >= firstIdx && colIndex < lastIdx,
  }
}

function markerAriaLabel(side: MilestoneSide, m: Milestone): string {
  return `${SIDE_LABELS[side]} milestone ${m.kind} — ${m.dateLabel} — ${STATUS_META[m.status].label}`
}

// ── Summary metrics (status derived from milestones) ─────────────────────────
const metricItems = computed<MetricItem[]>(() => {
  const count = (key: string) => projects.value.filter((p) => p.statusKey === key).length
  return [
    { label: 'Total Projects', value: String(projects.value.length) },
    { label: 'On Track', value: String(count('on-track')), tone: 'ok' },
    { label: 'Potential Delay', value: String(count('potential-delay')), tone: 'warn' },
    { label: 'Delayed', value: String(count('delayed')), tone: 'bad' },
  ]
})

// ── Milestone completion cards (Indo | Customer per event) ──────────────────
const { items: milestoneItems } = useMilestoneCompletion(projects)
</script>

<template>
  <div class="timeline-tab tab-enter">

    <!-- Loading (nothing to show yet) -->
    <div v-if="isLoading && !projects.length" class="tl-banner tl-loading" role="status" aria-live="polite">
      <i class="mdi mdi-loading mdi-spin" aria-hidden="true"></i>
      Loading project milestones…
    </div>

    <!-- Empty -->
    <div v-else-if="!projects.length" class="tl-banner tl-empty" role="status">
      <i class="mdi mdi-calendar-blank-outline" aria-hidden="true"></i>
      No project data available for the selected collaborative spaces.
    </div>

    <template v-else>
      <!-- Still loading: projects appear as they arrive -->
      <div v-if="milestonesLoading" class="tl-banner tl-loading" role="status" aria-live="polite">
        <i class="mdi mdi-loading mdi-spin" aria-hidden="true"></i>
        Loading project details… {{ loadedCount }} / {{ totalCount }}
      </div>

      <MetricStrip :items="[...metricItems, ...milestoneItems]" label="Timeline summary" dense />

      <!-- One card: legend toolbar, scrolling table, pagination footer -->
      <section class="table-card" aria-label="Project timeline">
        <div class="tl-legend" aria-label="Legend">
          <span class="legend-item">
            <span class="legend-shape legend-square"></span>
            Indo Milestone
          </span>
          <span class="legend-item">
            <span class="legend-shape legend-circle"></span>
            Customer Milestone
          </span>
          <span class="legend-sep" aria-hidden="true"></span>
          <span class="legend-item"><span class="legend-dot ok"></span> On Track</span>
          <span class="legend-item"><span class="legend-dot warn"></span> Potential Delay</span>
          <span class="legend-item"><span class="legend-dot bad"></span> Delayed</span>
        </div>

        <div class="timeline-wrapper">
          <table class="timeline-table">
            <caption class="sr-only">Indo and Customer milestones by month</caption>

            <thead>
              <!-- Row 1: year groups -->
              <tr>
                <th rowspan="2" scope="col" class="sticky-col proj-col head-cell">Project</th>
                <th rowspan="2" scope="col" class="sticky-col img-col head-cell">Image</th>
                <th rowspan="2" scope="col" class="sticky-col pct-col head-cell">%</th>
                <th
                  v-for="(yg, yi) in yearGroups"
                  :key="yg.year"
                  :colspan="yg.span"
                  scope="colgroup"
                  class="year-header"
                  :class="{ 'year-start': yi > 0 }"
                >
                  {{ yg.year }}
                </th>
              </tr>
              <!-- Row 2: month labels -->
              <tr>
                <th
                  v-for="(col, idx) in monthColumns"
                  :key="col.key"
                  scope="col"
                  class="month-header"
                  :class="{ 'is-today': isCurrentMonth(col), 'year-start': isYearStart(idx) }"
                >
                  {{ col.label }}
                  <span v-if="isCurrentMonth(col)" class="today-tag">Today</span>
                </th>
              </tr>
            </thead>

            <tbody>
              <!--
                Each project renders as TWO rows:
                  Row 1 — project identity + square Indo milestones
                  Row 2 — circular Customer milestones
              -->
              <template v-for="project in pagedProjects" :key="project.projectId">
                <tr
                  v-for="(side, sideIdx) in ROW_SIDES"
                  :key="side"
                  :class="sideIdx === 0 ? 'row-first' : 'row-second'"
                >
                  <template v-if="sideIdx === 0">
                    <th scope="rowgroup" rowspan="2" class="sticky-col proj-col proj-info">
                      <div class="proj-name" :title="project.projectLabel">
                        {{ project.projectLabel }}
                      </div>
                      <div class="proj-sub">
                        <StatusBadge :status="STATUS_META[project.statusKey].label" variant="plain" />
                      </div>
                    </th>

                    <td rowspan="2" class="sticky-col img-col img-info">
                      <ProjectThumb
                        :src="project.attributes.imageUrl"
                        :name="project.projectLabel"
                        :size="44"
                      />
                    </td>

                    <td rowspan="2" class="sticky-col pct-col pct-info">
                      <span class="pct-val">{{ Math.round(project.percentComplete ?? 0) }}%</span>
                      <div class="pct-bar-bg">
                        <div
                          class="pct-bar-fill"
                          :style="{ width: Math.min(100, project.percentComplete ?? 0) + '%' }"
                        ></div>
                      </div>
                    </td>
                  </template>

                  <td
                    v-for="(col, colIdx) in monthColumns"
                    :key="col.key"
                    :class="[
                      'timeline-cell',
                      side === 'INDO' ? 'indo-cell' : 'customer-cell',
                      {
                        ...trackClasses(project.projectId, side, colIdx),
                        'today-col': isCurrentMonth(col),
                        'year-start': isYearStart(colIdx),
                      },
                    ]"
                  >
                    <div
                      v-for="(m, mi) in markersAt(project.projectId, side, col)"
                      :key="m.kind + '-' + mi"
                      class="marker-wrap"
                      role="img"
                      :aria-label="markerAriaLabel(side, m)"
                    >
                      <span
                        :class="['marker', side === 'INDO' ? 'is-square' : 'is-circle', `status-${m.status}`]"
                      >
                        <span class="marker-label">{{ m.kind }}</span>
                      </span>
                      <span class="m-date">{{ m.dateLabel }}</span>
                    </div>
                  </td>
                </tr>
              </template>
            </tbody>
          </table>
        </div>

        <PaginationBar
          v-model:page="currentPage"
          v-model:page-size="pageSize"
          :total-pages="totalPages"
          :total-items="totalItems"
          :range-start="rangeStart"
          :range-end="rangeEnd"
        />
      </section>
    </template>
  </div>
</template>

