<script setup lang="ts">
import { computed, inject, ref } from 'vue'
import type { ActiveElement, ChartData, ChartEvent, ChartOptions } from 'chart.js'
import { Bar, Doughnut, Line } from 'vue-chartjs'
import { CHART_COLORS, setupChartTheme } from '@/dashboard/config/chartTheme'
import { colorForStatus, STATUS_META, toneForStatus } from '@/dashboard/constants/status'
import { useProjectSummary, type Drilldown } from '@/dashboard/composables/useProjectSummary'
import { COLLAB_FILTER_KEY, FED_SEARCH_KEY, PROJECT_MILESTONES_KEY } from '@/dashboard/injectionKeys'
import type { MetricItem, StatusKey, Tone } from '@/dashboard/types/project'
import MetricStrip from './common/MetricStrip.vue'
import PanelCard from './common/PanelCard.vue'
import ProjectDrawer from './common/ProjectDrawer.vue'

setupChartTheme()

const { loading: fedLoading, error: fedError, progress: fedProgress } = inject(FED_SEARCH_KEY)!
const { isAll: showingAllSpaces, clear: clearCollabFilter } = inject(COLLAB_FILTER_KEY)!

const {
  projects,
  loading: milestonesLoading,
  loadedCount,
  totalCount,
} = inject(PROJECT_MILESTONES_KEY)!

const {
  hasData,
  summary: dashboard,
  byStatus,
  byMassProductionMonth,
  byTopLevelTaskStatus,
  byBurnDownPoint,
} = useProjectSummary(projects)

// ── Drill-down panel ─────────────────────────────────────────────────────────
/** Recomputes from live data, so the panel stays current while projects load or the filter changes. */
const drilldownSource = ref<(() => Drilldown | null) | null>(null)
const drilldown = computed(() => drilldownSource.value?.() ?? null)

function openDrilldown(source: () => Drilldown | null) {
  if (source()) drilldownSource.value = source
}

function closeDrilldown() {
  drilldownSource.value = null
}

function openStatus(status: StatusKey) {
  const meta = STATUS_META[status]
  openDrilldown(() => byStatus([status], `${meta.label} projects`, meta.tone))
}

/** Click handler for a Chart.js chart: passes the clicked data index. */
// eslint-disable-next-line no-unused-vars -- parameter name in a function type
function onChartClick(handler: (index: number) => void) {
  return (_event: ChartEvent, elements: ActiveElement[]) => {
    if (elements.length) handler(elements[0]!.index)
  }
}

function pointerOnData(event: ChartEvent, elements: ActiveElement[]) {
  const canvas = event.native?.target as HTMLElement | undefined
  if (canvas) canvas.style.cursor = elements.length ? 'pointer' : 'default'
}

// ── Metrics ──────────────────────────────────────────────────────────────────
interface RawMetric {
  value: string
  subtitle: string
}

function toMetric(key: string, label: string, metric: RawMetric, tone?: Tone): MetricItem {
  return { key, label, value: metric.value, note: metric.subtitle, tone, clickable: true }
}

const metricItems = computed<MetricItem[]>(() => [
  toMetric('total', 'Total Projects', {
    ...dashboard.value.metrics.totalProjects,
    subtitle: showingAllSpaces.value ? 'from 3DEXPERIENCE' : 'in selected spaces',
  }),
  toMetric('on-track', 'On Track', dashboard.value.metrics.onTrack, 'ok'),
  toMetric('potential-delay', 'Potential Delay', dashboard.value.metrics.potentialDelay, 'warn'),
  toMetric('delayed', 'Delayed', dashboard.value.metrics.delayed, 'bad'),
  toMetric('late', 'Late Projects', dashboard.value.metrics.lateProjects),
  { ...toMetric('avg', 'Avg Progress', dashboard.value.metrics.avgProgress), clickable: false },
])

function onMetricSelect(item: MetricItem) {
  if (item.key === 'total') openDrilldown(() => byStatus([], 'All projects'))
  else if (item.key === 'late')
    openDrilldown(() => byStatus(['potential-delay', 'delayed'], 'Late projects', 'warn'))
  else if (item.key && item.key in STATUS_META) openStatus(item.key as StatusKey)
}

// ── Status mix (doughnut) ────────────────────────────────────────────────────
const totalProjects = computed(() =>
  dashboard.value.statusMix.reduce((sum, item) => sum + item.value, 0),
)

const statusMixSummary = computed(() =>
  dashboard.value.statusMix.map((item) => `${item.label} ${item.value}`).join(', '),
)

const donutData = computed<ChartData<'doughnut'>>(() => ({
  labels: dashboard.value.statusMix.map((item) => item.label),
  datasets: [
    {
      data: dashboard.value.statusMix.map((item) => item.value),
      backgroundColor: dashboard.value.statusMix.map((item) => colorForStatus(item.label, item.color)),
      borderColor: CHART_COLORS.surface,
      borderWidth: 3,
      hoverOffset: 6,
    },
  ],
}))

const donutOptions: ChartOptions<'doughnut'> = {
  responsive: true,
  maintainAspectRatio: false,
  cutout: '72%',
  onClick: onChartClick((index) => {
    const status = dashboard.value.statusMix[index]?.key
    if (status) openStatus(status)
  }),
  onHover: pointerOnData,
  plugins: {
    legend: { display: false },
  },
}

// ── Mass production (bar) ────────────────────────────────────────────────────
const barSummary = computed(() =>
  dashboard.value.massProduction.map((item) => `${item.month}: ${item.value}`).join(', '),
)

const barData = computed<ChartData<'bar'>>(() => ({
  labels: dashboard.value.massProduction.map((item) => item.month),
  datasets: [
    {
      label: 'Mass Production',
      data: dashboard.value.massProduction.map((item) => item.value),
      backgroundColor: CHART_COLORS.primary,
      hoverBackgroundColor: CHART_COLORS.primaryHover,
      borderRadius: 2,
      barPercentage: 0.55,
    },
  ],
}))

const barOptions: ChartOptions<'bar'> = {
  responsive: true,
  maintainAspectRatio: false,
  onClick: onChartClick((index) => openDrilldown(() => byMassProductionMonth(index))),
  onHover: pointerOnData,
  plugins: {
    legend: { display: false },
  },
  scales: {
    y: {
      beginAtZero: true,
      grid: { color: CHART_COLORS.grid },
      ticks: { stepSize: 1, color: CHART_COLORS.tick },
      border: { display: false },
    },
    x: {
      grid: { display: false },
      ticks: { color: CHART_COLORS.tick },
      border: { color: CHART_COLORS.grid },
    },
  },
}

// ── Burn down (line) ─────────────────────────────────────────────────────────
const lineData = computed<ChartData<'line'>>(() => ({
  labels: dashboard.value.burnDown.labels,
  datasets: [
    {
      label: 'Planned',
      data: dashboard.value.burnDown.planned,
      borderColor: CHART_COLORS.muted,
      backgroundColor: CHART_COLORS.muted,
      borderDash: [6, 4],
      borderWidth: 2,
      pointRadius: 2,
      tension: 0,
    },
    {
      label: 'Actual',
      data: dashboard.value.burnDown.actual,
      borderColor: CHART_COLORS.primary,
      backgroundColor: CHART_COLORS.primary,
      borderWidth: 2.5,
      pointRadius: 3.5,
      pointHoverRadius: 6,
      tension: 0,
    },
  ],
}))

const lineOptions: ChartOptions<'line'> = {
  responsive: true,
  maintainAspectRatio: false,
  interaction: { mode: 'index', intersect: false },
  onClick: onChartClick((index) => openDrilldown(() => byBurnDownPoint(index))),
  onHover: pointerOnData,
  plugins: {
    legend: {
      position: 'bottom',
      align: 'start',
      labels: { usePointStyle: true, boxWidth: 8, boxHeight: 8, padding: 16 },
    },
    tooltip: {
      callbacks: { footer: () => 'Click to see the projects' },
    },
  },
  scales: {
    y: {
      grid: { color: CHART_COLORS.grid },
      ticks: { color: CHART_COLORS.tick, maxTicksLimit: 5 },
      border: { display: false },
    },
    x: {
      grid: { display: false },
      ticks: { color: CHART_COLORS.tick },
      border: { color: CHART_COLORS.grid },
    },
  },
}

// ── Top level tasks (segmented bar + breakdown) ──────────────────────────────
const totalTopLevelTasks = computed(() =>
  dashboard.value.topLevelTasks.reduce((sum, task) => sum + task.value, 0),
)

const taskSegments = computed(() =>
  dashboard.value.topLevelTasks.map((task) => ({
    ...task,
    color: colorForStatus(task.label, task.color),
    tone: toneForStatus(task.label),
    percent: totalTopLevelTasks.value
      ? Math.round((task.value / totalTopLevelTasks.value) * 100)
      : 0,
  })),
)

/** Bar segments with a count (empty statuses stay in the breakdown only). */
const barSegments = computed(() => taskSegments.value.filter((task) => task.value > 0))

function openTopLevelTasks(status: StatusKey) {
  openDrilldown(() => byTopLevelTaskStatus(status))
}
</script>

<template>
  <div class="projects-tab tab-enter">
    <div v-if="fedLoading" class="fed-banner fed-loading" role="status" aria-live="polite">
      <i class="mdi mdi-loading mdi-spin" aria-hidden="true"></i>
      Fetching live Project Spaces from 3DExperience…
      <span v-if="fedProgress > 0" class="fed-progress-text">{{ fedProgress }}%</span>
      <span v-if="fedProgress > 0" class="fed-progress-bar-wrap" aria-hidden="true">
        <span class="fed-progress-bar" :style="{ width: fedProgress + '%' }"></span>
      </span>
    </div>
    <div v-else-if="fedError" class="fed-banner fed-error" role="alert">
      <i class="mdi mdi-alert-outline" aria-hidden="true"></i>
      Live data unavailable.
      <span class="fed-error-detail">{{ fedError }}</span>
    </div>
    <div v-else-if="milestonesLoading" class="fed-banner fed-loading" role="status" aria-live="polite">
      <i class="mdi mdi-loading mdi-spin" aria-hidden="true"></i>
      Loading project details… {{ loadedCount }} / {{ totalCount }}
    </div>
    <div v-else-if="!hasData" class="fed-banner fed-error" role="status">
      <i class="mdi mdi-information-outline" aria-hidden="true"></i>
      <template v-if="showingAllSpaces">No matching projects found.</template>
      <template v-else>
        No projects in the selected collaborative spaces.
        <button type="button" class="banner-link" @click="clearCollabFilter">Show all spaces</button>
      </template>
    </div>

    <template v-if="hasData">
      <MetricStrip :items="metricItems" label="Portfolio summary" @select="onMetricSelect" />

      <div class="charts-grid">
        <PanelCard title="Project Status Mix" subtitle="click a segment for details">
          <div class="donut-wrapper">
            <div
              class="donut-chart-box"
              role="img"
              :aria-label="`Project status mix: ${statusMixSummary}`"
            >
              <Doughnut :data="donutData" :options="donutOptions" />
              <div class="donut-center-text">
                <span class="donut-total">{{ totalProjects }}</span>
                <span class="donut-caption">Projects</span>
              </div>
            </div>
            <ul class="legend-list">
              <li v-for="item in dashboard.statusMix" :key="item.label">
                <button type="button" class="legend-item legend-btn" @click="openStatus(item.key)">
                  <span
                    class="dot"
                    :style="{ backgroundColor: colorForStatus(item.label, item.color) }"
                  ></span>
                  <span class="legend-label">{{ item.label }}</span>
                  <span class="legend-val">{{ item.value }}</span>
                </button>
              </li>
            </ul>
          </div>
        </PanelCard>

        <PanelCard title="Mass Production Schedule" subtitle="by MP target · click a bar">
          <div
            class="chart-box bar-chart-box"
            role="img"
            :aria-label="`Mass production schedule. ${barSummary}`"
          >
            <Bar :data="barData" :options="barOptions" />
          </div>
        </PanelCard>
      </div>

      <div class="charts-grid">
        <PanelCard title="Top Level Tasks" :subtitle="`${totalTopLevelTasks} tasks`">
          <div class="segmented-wrapper">
            <div class="segmented-bar">
              <button
                v-for="task in barSegments"
                :key="task.label"
                type="button"
                :class="['segment', `tone-${task.tone}`]"
                :style="{ backgroundColor: task.color, flex: task.value }"
                :aria-label="`${task.label}: ${task.value} tasks. Show projects`"
                @click="openTopLevelTasks(task.key)"
              >
                {{ task.value }}
              </button>
            </div>
            <ul class="task-breakdown">
              <li v-for="task in taskSegments" :key="task.label">
                <button
                  type="button"
                  class="breakdown-row"
                  :disabled="task.value === 0"
                  @click="openTopLevelTasks(task.key)"
                >
                  <span class="dot" :style="{ backgroundColor: task.color }"></span>
                  <span class="legend-label">{{ task.label }}</span>
                  <span class="breakdown-pct">{{ task.percent }}%</span>
                  <span class="legend-val">{{ task.value }}</span>
                  <i class="mdi mdi-chevron-right chevron" aria-hidden="true"></i>
                </button>
              </li>
            </ul>
          </div>
        </PanelCard>

        <PanelCard title="Burn Down" subtitle="remaining tasks / week · click a point">
          <div
            class="chart-box line-chart-box"
            role="img"
            aria-label="Burn down chart: planned versus actual remaining tasks by week"
          >
            <Line :data="lineData" :options="lineOptions" />
          </div>
        </PanelCard>
      </div>
    </template>

    <ProjectDrawer :drilldown="drilldown" @close="closeDrilldown" />
  </div>
</template>

<style scoped>
.projects-tab {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  /* Fill the main area, but grow (and scroll the page) when content needs more room. */
  flex: 1 0 auto;
}

.charts-grid {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: var(--space-3);
  /* Rows share the free space but never shrink below their content (min-height: auto),
     so on short/zoomed screens the page scrolls instead of squashing the charts. */
  flex: 1 1 0;
}

@media (max-width: 1024px) {
  .charts-grid {
    grid-template-columns: 1fr;
    flex: none;
  }
}

/* Doughnut */
.donut-wrapper {
  display: flex;
  flex: 1;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--space-5);
}

.donut-chart-box {
  position: relative;
  width: 160px;
  height: 160px;
}

.donut-center-text {
  position: absolute;
  top: 50%;
  left: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  transform: translate(-50%, -50%);
}

.donut-total {
  font-size: 2.5rem;
  font-weight: 700;
  font-stretch: var(--stretch-display);
  line-height: 1;
  color: var(--ink-900);
}

.donut-caption {
  margin-top: 2px;
  font-size: var(--text-xs);
  color: var(--ink-500);
}

/* Legends */
.legend-list {
  padding: 0;
  margin: 0;
  list-style: none;
}

.legend-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-width: 12rem;
}

.legend-btn,
.breakdown-row {
  width: 100%;
  padding: var(--space-1) var(--space-2);
  font: inherit;
  text-align: left;
  cursor: pointer;
  background: none;
  border: none;
  border-radius: var(--radius-sm);
  transition: background-color 0.15s;
}

.legend-btn:hover,
.breakdown-row:hover:not(:disabled) {
  background: var(--surface-sunken);
}

.breakdown-row:disabled {
  cursor: default;
  opacity: 0.6;
}

.legend-list .legend-label {
  flex: 1;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.dot {
  display: inline-block;
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 50%;
}

.legend-label {
  font-size: var(--text-sm);
  color: var(--ink-600);
}

.legend-val {
  min-width: 1.5rem;
  margin-left: var(--space-2);
  font-size: var(--text-base);
  font-weight: 700;
  color: var(--ink-900);
  text-align: right;
}

.chart-box {
  position: relative;
  flex: 1;
  min-height: 0;
}

/* Chart.js sizes the canvas from this box; positioning it absolutely stops the canvas
   from feeding back into the box size (which caused 1px overflow and a stray scrollbar). */
.chart-box :deep(canvas) {
  position: absolute;
  inset: 0;
}

.bar-chart-box {
  min-height: 180px;
}

.line-chart-box {
  min-height: 180px;
}

/* Segmented bar + breakdown */
.segmented-wrapper {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--space-3);
  justify-content: center;
}

.task-breakdown {
  display: flex;
  flex-direction: column;
  padding: 0;
  margin: 0;
  list-style: none;
}

.task-breakdown li + li {
  border-top: 1px solid var(--line-soft);
}

.breakdown-row {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding-block: var(--space-2);
}

.breakdown-row .legend-label {
  flex: 1;
}

.breakdown-pct {
  font-size: var(--text-xs);
  color: var(--ink-500);
}

.chevron {
  font-size: 1rem;
  color: var(--ink-400);
}

.segmented-bar {
  display: flex;
  gap: 2px;
  width: 100%;
  height: 40px;
  overflow: hidden;
  border-radius: var(--radius-sm);
}

.segment {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 2rem;
  padding: 0;
  font: inherit;
  font-size: var(--text-base);
  font-weight: 700;
  color: var(--ink-950);
  cursor: pointer;
  border: none;
  transition: filter 0.15s;
}

.segment:hover {
  filter: brightness(0.92);
}

.segment.tone-bad {
  color: #fff;
}

/* ── Federated Search banner ─────────────────────────────────────────────── */
.fed-banner {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-sm);
  font-size: var(--text-sm);
  font-weight: 500;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.fed-loading {
  background: color-mix(in srgb, var(--brand) 12%, transparent);
  color: var(--brand);
}

.fed-loading .mdi-loading {
  animation: spin 1s linear infinite;
}

.fed-progress-text {
  margin-left: auto;
  font-size: var(--text-xs);
  font-weight: 600;
  min-width: 2.5rem;
  text-align: right;
}

.fed-progress-bar-wrap {
  display: block;
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 3px;
  background: color-mix(in srgb, var(--brand) 25%, transparent);
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  overflow: hidden;
}

.fed-progress-bar {
  display: block;
  height: 100%;
  background: var(--brand);
  transition: width 0.3s ease;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.fed-error {
  background: color-mix(in srgb, #dd4b39 10%, transparent);
  color: #c0392b;
}

.fed-error-detail {
  margin-left: var(--space-2);
  font-size: var(--text-xs);
  opacity: 0.75;
  font-weight: 400;
  word-break: break-all;
}

.banner-link {
  margin-left: var(--space-2);
  padding: 0;
  font: inherit;
  font-weight: 650;
  color: var(--brand);
  text-decoration: underline;
  cursor: pointer;
  background: none;
  border: none;
}
</style>
