const Util = {};

/** Security context selected in the widget's "Credentials" preference, e.g. "ctx::VPLMProjectLeader.Org.Space". */
Util.getCTX = function () {
  try {
    return window.widget ? window.widget.getValue("ctx_credentials") : "";
  } catch (error) {
    return undefined;
  }
};

export default Util;
