<script setup lang="ts">
import { computed } from 'vue'

const props = withDefaults(
  defineProps<{
    totalPages: number
    totalItems: number
    rangeStart: number
    rangeEnd: number
    /** Noun for the count, e.g. "projects" */
    itemLabel?: string
    pageSizes?: number[]
  }>(),
  { itemLabel: 'projects', pageSizes: () => [10, 25, 50] },
)

const page = defineModel<number>('page', { required: true })
const pageSize = defineModel<number>('pageSize', { required: true })

/** Page buttons: first, last, and a window around the current page, with gaps. */
const pageButtons = computed<Array<number | 'gap'>>(() => {
  const total = props.totalPages
  const current = page.value
  const wanted = new Set([1, total, current - 1, current, current + 1])
  const pages = Array.from(wanted)
    .filter((p) => p >= 1 && p <= total)
    .sort((a, b) => a - b)

  const result: Array<number | 'gap'> = []
  pages.forEach((p, i) => {
    if (i > 0 && p - pages[i - 1]! > 1) result.push('gap')
    result.push(p)
  })
  return result
})
</script>

<template>
  <nav class="pagination" aria-label="Pagination">
    <span class="range" aria-live="polite">
      <template v-if="totalItems">
        <strong>{{ rangeStart }}–{{ rangeEnd }}</strong> of <strong>{{ totalItems }}</strong>
        {{ itemLabel }}
      </template>
      <template v-else>No {{ itemLabel }}</template>
    </span>

    <div class="controls">
      <label class="size">
        Rows
        <select v-model.number="pageSize" aria-label="Rows per page">
          <option v-for="size in pageSizes" :key="size" :value="size">{{ size }}</option>
        </select>
      </label>

      <button
        type="button"
        class="page-btn icon"
        :disabled="page <= 1"
        aria-label="Previous page"
        @click="page--"
      >
        <i class="mdi mdi-chevron-left" aria-hidden="true"></i>
      </button>
      <template v-for="(p, i) in pageButtons" :key="p === 'gap' ? `gap-${i}` : p">
        <span v-if="p === 'gap'" class="gap" aria-hidden="true">…</span>
        <button
          v-else
          type="button"
          :class="['page-btn', { current: p === page }]"
          :aria-current="p === page ? 'page' : undefined"
          :aria-label="`Page ${p}`"
          @click="page = p"
        >
          {{ p }}
        </button>
      </template>
      <button
        type="button"
        class="page-btn icon"
        :disabled="page >= totalPages"
        aria-label="Next page"
        @click="page++"
      >
        <i class="mdi mdi-chevron-right" aria-hidden="true"></i>
      </button>
    </div>
  </nav>
</template>

