import type { ProjectDetail, ProjectTask } from '@/dashboard/composables/useProjectMilestones'
import { parseApiDate } from './date'

/**
 * The date shown for a milestone on every tab (timeline markers, Event Status cells,
 * drill-down panel). Change it here to switch which task date is used.
 */
export function milestoneDate(task: ProjectTask): Date | null {
  return parseApiDate(task.dueDate ?? task.forecastFinishDate ?? task.estimatedStartDate)
}

/**
 * Milestones are named "<EVENT> <SIDE>", e.g. "PP0 INDO" / "PP0 CUSTOMER".
 * A name without a side suffix (e.g. "M1") is treated as the Customer milestone.
 */
export type MilestoneSide = 'INDO' | 'CUSTOMER'

/** Display order of the two sides. */
export const MILESTONE_SIDES: MilestoneSide[] = ['INDO', 'CUSTOMER']

export const SIDE_LABELS: Record<MilestoneSide, string> = {
  INDO: 'Indo',
  CUSTOMER: 'Customer',
}

export interface ParsedMilestoneName {
  /** Event key, upper-cased with single spaces, e.g. "PP0" */
  event: string
  side: MilestoneSide
}

const SIDE_SUFFIX = /^(.*?)\s+(INDO|CUSTOMER)$/i

/** Splits a milestone title into event and side; null for an empty title. */
export function parseMilestoneName(title: unknown): ParsedMilestoneName | null {
  const normalised = String(title ?? '').trim().replace(/\s+/g, ' ').toUpperCase()
  if (!normalised) return null
  const match = SIDE_SUFFIX.exec(normalised)
  return match
    ? { event: match[1], side: match[2] as MilestoneSide }
    : { event: normalised, side: 'CUSTOMER' }
}

/** Distinct events across projects, in first-seen (sequence) order. */
export function collectMilestoneEvents(projects: ProjectDetail[]): string[] {
  const events = new Set<string>()
  for (const project of projects) {
    for (const milestone of project.milestones) {
      const parsed = parseMilestoneName(milestone.title)
      if (parsed) events.add(parsed.event)
    }
  }
  return Array.from(events)
}

/** A project's first milestone for the given event and side. */
export function findMilestone(
  project: ProjectDetail,
  event: string,
  side: MilestoneSide,
): ProjectTask | undefined {
  return project.milestones.find((m) => {
    const parsed = parseMilestoneName(m.title)
    return parsed?.event === event && parsed.side === side
  })
}
