<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { STATUS_META } from '@/dashboard/constants/status'
import { formatDayLabel } from '@/dashboard/utils/date'
import {
  collectMilestoneEvents,
  findMilestone,
  milestoneDate,
  MILESTONE_SIDES,
  SIDE_LABELS,
} from '@/dashboard/utils/milestones'
import { classifyTask, isTaskComplete } from '@/dashboard/utils/projectStatus'
import { NO_COLLAB_SPACE } from '@/dashboard/composables/useCollabSpaceFilter'
import type { Drilldown } from '@/dashboard/composables/useProjectSummary'
import type { ProjectDetail } from '@/dashboard/composables/useProjectMilestones'
import ProjectThumb from './ProjectThumb.vue'
import StatusBadge from './StatusBadge.vue'

const props = defineProps<{
  /** Panel contents; null closes the panel */
  drilldown: Drilldown | null
}>()

const emit = defineEmits<{ close: [] }>()

const query = ref('')
const expanded = ref<Set<string>>(new Set())
const panel = ref<HTMLElement | null>(null)
let returnFocusTo: HTMLElement | null = null

const entries = computed(() => {
  const all = props.drilldown?.entries ?? []
  const q = query.value.trim().toLowerCase()
  if (!q) return all
  return all.filter(({ project }) =>
    [project.projectLabel, project.collabSpace, project.attributes.location, project.attributes.model]
      .join(' ')
      .toLowerCase()
      .includes(q),
  )
})

watch(
  () => props.drilldown,
  async (value, previous) => {
    query.value = ''
    expanded.value = new Set()
    if (value && !previous) {
      returnFocusTo = document.activeElement as HTMLElement | null
      document.addEventListener('keydown', onKeydown)
      await nextTick()
      panel.value?.focus()
    } else if (!value) {
      document.removeEventListener('keydown', onKeydown)
      returnFocusTo?.focus?.()
    }
  },
)

onBeforeUnmount(() => document.removeEventListener('keydown', onKeydown))

function onKeydown(event: KeyboardEvent) {
  if (event.key === 'Escape') emit('close')
}

function toggle(id: string) {
  const next = new Set(expanded.value)
  if (next.has(id)) next.delete(id)
  else next.add(id)
  expanded.value = next
}

interface MilestoneCell {
  date: string
  status: 'on-track' | 'potential-delay' | 'delayed'
  done: boolean
}

/** Indo / Customer milestone per event, for the expanded project. */
function milestoneRows(project: ProjectDetail) {
  return collectMilestoneEvents([project]).map((event) => ({
    event,
    cells: MILESTONE_SIDES.map((side): MilestoneCell | null => {
      const task = findMilestone(project, event, side)
      if (!task) return null
      const date = milestoneDate(task)
      return { date: date ? formatDayLabel(date) : '-', status: classifyTask(task), done: isTaskComplete(task) }
    }),
  }))
}

const pct = (p: ProjectDetail) => Math.round(p.percentComplete ?? 0)
</script>

<template>
  <Teleport to="body">
    <Transition name="drawer">
      <div v-if="drilldown" class="drawer-root">
        <div class="scrim" aria-hidden="true" @click="emit('close')"></div>

        <aside
          ref="panel"
          class="drawer"
          role="dialog"
          aria-modal="true"
          :aria-label="drilldown.title"
          tabindex="-1"
        >
          <header :class="['drawer-head', drilldown.tone && `tone-${drilldown.tone}`]">
            <div class="head-text">
              <h2 class="drawer-title">{{ drilldown.title }}</h2>
              <p class="drawer-sub">{{ drilldown.subtitle }}</p>
            </div>
            <button type="button" class="close-btn" aria-label="Close panel" @click="emit('close')">
              <i class="mdi mdi-close" aria-hidden="true"></i>
            </button>
          </header>

          <div v-if="drilldown.entries.length > 5" class="drawer-search">
            <i class="mdi mdi-magnify" aria-hidden="true"></i>
            <input
              v-model="query"
              type="search"
              placeholder="Filter by project, space, location, model"
              aria-label="Filter projects in this panel"
            />
          </div>

          <ul class="entry-list">
            <li v-for="entry in entries" :key="entry.project.projectId" class="entry">
              <div class="entry-main">
                <ProjectThumb
                  :src="entry.project.attributes.imageUrl"
                  :name="entry.project.projectLabel"
                  :size="44"
                />
                <div class="entry-body">
                  <div class="entry-top">
                    <span class="entry-name" :title="entry.project.projectLabel">
                      {{ entry.project.projectLabel }}
                    </span>
                    <StatusBadge :status="STATUS_META[entry.project.statusKey].label" />
                  </div>

                  <div class="entry-meta">
                    <span title="Collaborative space">
                      <i class="mdi mdi-account-group-outline" aria-hidden="true"></i>
                      {{ entry.project.collabSpace || NO_COLLAB_SPACE }}
                    </span>
                    <span v-if="entry.project.attributes.location">
                      <i class="mdi mdi-map-marker-outline" aria-hidden="true"></i>
                      {{ entry.project.attributes.location }}
                    </span>
                    <span v-if="entry.project.attributes.model">
                      <i class="mdi mdi-car-outline" aria-hidden="true"></i>
                      {{ entry.project.attributes.model }}
                    </span>
                  </div>

                  <div class="entry-progress">
                    <span class="bar" aria-hidden="true">
                      <span class="fill" :style="{ width: Math.min(100, pct(entry.project)) + '%' }"></span>
                    </span>
                    <span class="pct">{{ pct(entry.project) }}%</span>
                    <span v-if="entry.note" class="note">{{ entry.note }}</span>
                  </div>

                  <ul v-if="entry.details?.length" class="details">
                    <li v-for="(line, i) in entry.details" :key="i">{{ line }}</li>
                  </ul>

                  <button
                    v-if="entry.project.milestones.length"
                    type="button"
                    class="expand-btn"
                    :aria-expanded="expanded.has(entry.project.projectId)"
                    @click="toggle(entry.project.projectId)"
                  >
                    <i
                      :class="['mdi', expanded.has(entry.project.projectId) ? 'mdi-chevron-up' : 'mdi-chevron-down']"
                      aria-hidden="true"
                    ></i>
                    {{ expanded.has(entry.project.projectId) ? 'Hide' : 'Show' }} milestones
                  </button>
                </div>
              </div>

              <table v-if="expanded.has(entry.project.projectId)" class="ms-table">
                <thead>
                  <tr>
                    <th scope="col">Event</th>
                    <th v-for="side in MILESTONE_SIDES" :key="side" scope="col">{{ SIDE_LABELS[side] }}</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="row in milestoneRows(entry.project)" :key="row.event">
                    <th scope="row">{{ row.event }}</th>
                    <td v-for="(cell, i) in row.cells" :key="i">
                      <span v-if="cell" class="ms-cell">
                        <span :class="['lamp', `status-${cell.status}`]" aria-hidden="true"></span>
                        {{ cell.date }}
                        <i v-if="cell.done" class="mdi mdi-check done" title="Completed" aria-label="Completed"></i>
                      </span>
                      <span v-else class="muted">-</span>
                    </td>
                  </tr>
                </tbody>
              </table>
            </li>

            <li v-if="!entries.length" class="empty">
              {{ drilldown.entries.length ? 'No projects match this filter.' : 'No projects in this selection.' }}
            </li>
          </ul>
        </aside>
      </div>
    </Transition>
  </Teleport>
</template>

