/**
 * 3DEXPERIENCE service URLs, resolved at runtime so the same build works on any server.
 *
 * Inside 3DDashboard (in this order):
 *   1. i3DXCompassServices for the widget's platform (`x3dPlatformId`);
 *   2. otherwise derived from a known server name:
 *      - 3DEXPERIENCE cloud: <tenant>-<region>-ifwe|space.3dexperience.3ds.com →
 *        <tenant>-<region>-space…/enovia and <tenant>-<region>-fedsearch…/federated;
 *      - on-premise: the dashboard origin + /3dspace and /federated.
 *   The .env URLs are never used inside 3DDashboard; if no URL can be found,
 *   resolvePlatformUrls() throws so the widget shows an error instead of
 *   silently talking to another server.
 *
 * Standalone (widget page opened directly, for local development): the .env URLs.
 *
 * Inside 3DDashboard, requests are sent through DS/WAFData (see api/transport.js).
 */

import { setWafData, transportName } from "@/api/transport";

const COMPASS_MODULE = "DS/i3DXCompassServices/i3DXCompassServices";
const WAFDATA_MODULE = "DS/WAFData/WAFData";
const LOOKUP_TIMEOUT_MS = 10000;

/** Paths of the services on an on-premise server, relative to the dashboard origin. */
const ON_PREMISE_PATHS = {
  spaceUrl: "/3dspace",
  searchUrl: "/federated",
};

/** Services to resolve; `names` are the compass service names tried in order. */
const SERVICES = [
  { key: "spaceUrl", label: "3DSpace", names: ["3DSpace"] },
  { key: "searchUrl", label: "3DSearch", names: ["3DSearch", "Federated", "FederatedSearch"] },
];

/** Cloud host names: <tenant>-<region>-<service>.3dexperience.3ds.com */
const CLOUD_HOST = /^(.+)-(ifwe|space|fedsearch|3dswym|3dpassport|3ddashboard)\.(3dexperience\.3ds\.com)$/i;

const trimSlash = (url) => (url ? String(url).replace(/\/+$/, "") : "");

const platform = {
  /** Platform/tenant id (e.g. "OnPremise" or "R1132101701695"); null until resolved. */
  platformId: null,
  spaceUrl: "",
  searchUrl: "",
  /** Where each URL came from, for diagnostics: "compass" | "dashboard-origin" | "env". */
  source: {},
};

/** Current service URLs (empty until resolvePlatformUrls() completes). */
export function getPlatform() {
  return platform;
}

/** Platform id of the current dashboard, or `fallback` when running standalone. */
export function getTenant(fallback) {
  return platform.platformId || fallback;
}

function withTimeout(promise, label) {
  return Promise.race([
    promise,
    new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`${label} timed out`)), LOOKUP_TIMEOUT_MS)
    ),
  ]);
}

/** The AMD loader provided by 3DDashboard (`require`, or `requirejs`). */
function amdRequire() {
  if (typeof window.require === "function") return window.require;
  if (typeof window.requirejs === "function") return window.requirejs;
  return null;
}

/** Loads a 3DDashboard AMD module (async form: loaded on demand by the platform). */
function loadAmdModule(name) {
  return new Promise((resolve, reject) => {
    const load = amdRequire();
    if (!load) {
      reject(new Error("no AMD loader (require) available"));
      return;
    }
    load([name], resolve, reject);
  });
}

/** Resolves { url, platformId } for one service. */
function lookupServiceUrl(compass, serviceName, platformId) {
  return new Promise((resolve, reject) => {
    compass.getServiceUrl({
      serviceName,
      platformId: platformId || undefined,
      onComplete: (result) => {
        // With a platformId the result is the URL string; without one it is a
        // list of { platformId, url } entries, one per platform the user can access.
        if (typeof result === "string" && result) {
          resolve({ url: result, platformId });
          return;
        }
        const first = Array.isArray(result) ? result[0] : null;
        if (first?.url) resolve(first);
        else reject(new Error(`${serviceName} URL not found`));
      },
      onFailure: () => reject(new Error(`${serviceName} URL lookup failed`)),
    });
  });
}

/** Origin of the 3DDashboard page hosting this widget (the parent frame), if known. */
function dashboardOrigin() {
  try {
    const ancestors = window.location.ancestorOrigins;
    if (ancestors && ancestors.length) return ancestors[ancestors.length - 1];
  } catch (err) {
    // not available in this browser
  }
  try {
    if (document.referrer) return new URL(document.referrer).origin;
  } catch (err) {
    // invalid referrer
  }
  return null;
}

async function resolveFromCompass(platformId) {
  let compass;
  try {
    compass = await withTimeout(loadAmdModule(COMPASS_MODULE), "i3DXCompassServices load");
  } catch (err) {
    console.warn("[platformUrls] i3DXCompassServices unavailable:", err.message);
    return;
  }

  await Promise.all(
    SERVICES.map(async ({ key, label, names }) => {
      for (const name of names) {
        try {
          // eslint-disable-next-line no-await-in-loop
          const found = await withTimeout(lookupServiceUrl(compass, name, platformId), `${name} lookup`);
          platform[key] = trimSlash(found.url);
          platform.source[key] = `compass:${name}`;
          platform.platformId = platform.platformId || found.platformId || null;
          return;
        } catch (err) {
          console.warn(`[platformUrls] ${label} lookup as "${name}" failed:`, err.message);
        }
      }
    })
  );
}

/** Cloud service URLs derived from any cloud host name of the same tenant, or null. */
function cloudUrlsFrom(url) {
  let host;
  try {
    host = new URL(url).hostname;
  } catch (err) {
    return null;
  }
  const match = CLOUD_HOST.exec(host);
  if (!match) return null;
  const [, tenantRegion, , domain] = match;
  return {
    spaceUrl: `https://${tenantRegion}-space.${domain}/enovia`,
    searchUrl: `https://${tenantRegion}-fedsearch.${domain}/federated`,
  };
}

/** Uses WAFData for all requests when available (required on the 3DEXPERIENCE cloud). */
async function setupTransport() {
  try {
    setWafData(await withTimeout(loadAmdModule(WAFDATA_MODULE), "WAFData load"));
  } catch (err) {
    console.warn("[platformUrls] WAFData unavailable, using direct requests:", err.message);
  }
}

/** Fills URLs compass could not provide from known server names (cloud or on-premise). */
function resolveFromKnownHosts() {
  const origin = dashboardOrigin();
  const cloud = cloudUrlsFrom(platform.spaceUrl) || (origin && cloudUrlsFrom(origin));

  for (const { key } of SERVICES) {
    if (platform[key]) continue;
    if (cloud) {
      platform[key] = cloud[key];
      platform.source[key] = "cloud-host";
    } else if (origin) {
      platform[key] = origin + ON_PREMISE_PATHS[key];
      platform.source[key] = "dashboard-origin";
    }
  }
}

function resolveFromEnv() {
  platform.spaceUrl = trimSlash(process.env.VUE_APP_SPACE_URL);
  platform.searchUrl = trimSlash(process.env.VUE_APP_SEARCH_URL);
  platform.source = { spaceUrl: "env", searchUrl: "env" };
}

/**
 * Determines the 3DSpace and 3DSearch URLs for the platform the widget runs on.
 * @param {object} widget        the 3DDashboard widget object
 * @param {boolean} standalone   true when running outside 3DDashboard
 */
export async function resolvePlatformUrls(widget, standalone) {
  if (standalone) {
    resolveFromEnv();
  } else {
    platform.platformId = widget?.getValue?.("x3dPlatformId") || null;
    await Promise.all([setupTransport(), resolveFromCompass(platform.platformId)]);
    resolveFromKnownHosts();

    const missing = SERVICES.filter(({ key }) => !platform[key]).map(({ label }) => label);
    if (missing.length) {
      throw new Error(`Could not determine the ${missing.join(" and ")} URL for this platform.`);
    }
  }

  console.info(
    `[platformUrls] 3DSpace: ${platform.spaceUrl} (${platform.source.spaceUrl}), ` +
      `3DSearch: ${platform.searchUrl} (${platform.source.searchUrl}), ` +
      `platform: ${platform.platformId ?? "-"}, requests via ${transportName()}`
  );
  return platform;
}
