import { createStore } from "vuex";

export default createStore({
  state: {
    widgetLoad: false,
    initError: "",
  },
  getters: {
    GET_WIDGET_LOAD: (state) => state.widgetLoad,
    GET_INIT_ERROR: (state) => state.initError,
  },
  mutations: {
    UPDATE_WIDGET_LOAD(state, payload) {
      state.widgetLoad = payload;
    },
    UPDATE_INIT_ERROR(state, payload) {
      state.initError = payload;
    },
  },
  actions: {
    SET_TO_WIDGET_LOAD({ commit }, payload) {
      commit("UPDATE_WIDGET_LOAD", payload);
    },
    SET_INIT_ERROR({ commit }, payload) {
      commit("UPDATE_INIT_ERROR", payload);
    },
  },
});
