import store from "@/store";
import services from "@/services";
import { getPlatform, resolvePlatformUrls } from "@/config/platformUrls";
import { isStandalone } from "@/config/widgetConfig";

const initApp = {};

/** Resolves the 3DEXPERIENCE service URLs for the platform the widget runs on. */
initApp.platformUrls = async function (widget) {
  await resolvePlatformUrls(widget, isStandalone());
};

/** Shows a startup error in the widget instead of leaving it blank. */
initApp.fail = function (err) {
  console.error("[initApp] Widget start-up failed:", err);
  store.dispatch("SET_INIT_ERROR", err?.message || String(err));
};

initApp.widgetLoad = async function () {
  store.dispatch("SET_TO_WIDGET_LOAD", true);
};

/**
 * Registers the "Credentials" widget preference (`ctx_credentials`), listing every
 * role.organization.collabspace the user can use and defaulting to their preferred one.
 */
initApp.userCtxCollabspaces = async function (widget) {
  try {
    const { data } = await services.enovia().getCollabspaces();
    const { role, organization, collabspace } = data.preferredcredentials;
    const defaultCtx = `ctx::${role.name}.${organization.name}.${collabspace.name}`;

    widget.addPreference({
      name: "ctx_credentials",
      type: "list",
      label: "Credentials",
      defaultValue: defaultCtx,
      options: listCredentials(data).map((credential) => ({
        label: credential,
        value: `ctx::${credential}`,
      })),
    });
  } catch (err) {
    throw new Error(
      `Could not read your credentials from 3DSpace (${getPlatform().spaceUrl}). ` +
        "Check that you are logged in and that this server allows requests from the widget."
    );
  }
};

/** Flattens the collabspaces response into "role.organization.collabspace" strings. */
function listCredentials(data) {
  const results = [];
  try {
    data.collabspaces.forEach((collabspace) => {
      collabspace.couples.forEach((couple) => {
        results.push(`${couple.role.name}.${couple.organization.name}.${collabspace.name}`);
      });
    });
  } catch (error) {
    // Malformed response: return whatever was collected.
  }
  return results;
}

export default initApp;
